WITH flagged AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL 20 MINUTES THEN 1 ELSE 0 END AS session_start_flag FROM device_readings), sessions_device_readings AS (SELECT id, device_code, reading_ts, humidity, status_bits, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT id, device_code, reading_ts, humidity, session_id FROM sessions_device_readings ORDER BY id NULLS FIRST
